# region: render
def render(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
    return out

# region: sift
def sift(xs):
    return [v for v in xs if v % 2 == 0]

# region: intake
def intake(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: emit
def emit(summary, bar=3):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n // bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return emit(intake(sift(render(raw))))

